<?php require 'config.php'; $u=require_user();$page_title='Customer Dashboard — HOSTNEIL';$d=store_read();$orders=array_values(array_filter($d['orders'],fn($o)=>($o['user_email']??$o['email'])===$u['email']));$payments=array_values(array_filter($d['payments'],fn($p)=>$p['email']===$u['email']));require 'includes/header.php'; ?><section class="section"><div class="wrap"><span class="eyebrow">CUSTOMER AREA</span><h1 style="font-size:3rem">Hello, <span class="gradient"><?= h($u['name']) ?></span></h1><p>Track your order status and payment references. Services are activated manually after verification and provisioning.</p><div class="adminnav"><a href="order.php">+ New order</a><a href="vps.php">Request VPS quote</a><a href="logout.php">Log out</a></div><h2>Your orders</h2><div class="tablewrap"><table class="table"><tr><th>Order</th><th>Service</th><th>Plan</th><th>Price</th><th>Status</th><th>Date</th></tr><?php foreach($orders as $o): ?><tr><td>#<?= (int)$o['id'] ?></td><td><?= h($o['service']) ?></td><td><?= h($o['plan']) ?></td><td><?= money($o['price']) ?></td><td><span class="pill <?= h($o['status']) ?>"><?= h($o['status']) ?></span></td><td><?= h($o['created']) ?></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="6">No orders yet.</td></tr><?php endif; ?></table></div><h2 style="margin-top:35px">Payment references</h2><div class="tablewrap"><table class="table"><tr><th>ID</th><th>Order</th><th>Method</th><th>Amount</th><th>Reference</th><th>Status</th></tr><?php foreach($payments as $p): ?><tr><td>#<?= (int)$p['id'] ?></td><td>#<?= (int)$p['order_id'] ?></td><td><?= h($p['method']) ?></td><td><?= money($p['amount']) ?></td><td><?= h($p['transaction_id']) ?></td><td><span class="pill <?= h($p['status']) ?>"><?= h($p['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="6">No payment references submitted.</td></tr><?php endif; ?></table></div></div></section><?php require 'includes/footer.php'; ?>